class DocumentExtractor:
    def __init__(self, model_name: str):
        self.model_name = model_name
        self.extractions = []
        self.schemas = {}
        self.schemas["receipt"] = "Extract merchant, date, and total"
        self.schemas["invoice"] = "Extract vendor, invoice_number, and amount_due"
        self.schemas["screenshot"] = "Extract app_name and visible_text"

    def add_schema(self, doc_type: str, prompt: str):
        self.schemas[doc_type] = prompt

    def extract(self, image_path: str, doc_type: str) -> dict:
        if doc_type not in self.schemas:
            raise ValueError(f"Unknown document type: {doc_type}")
        if doc_type == "receipt":
            result = {"merchant": "MockStore", "total": 9.99}
        elif doc_type == "invoice":
            result = {"vendor": "MockVendor", "amount_due": 100.0}
        else:
            result = {"app_name": "MockApp", "visible_text": ["hello"]}
        self.extractions.append({
            "image": image_path,
            "doc_type": doc_type,
            "schema": self.schemas[doc_type],
            "result": result,
        })
        return result

    def summary(self) -> dict:
        by_type = {}
        for item in self.extractions:
            by_type[item["doc_type"]] = by_type.get(item["doc_type"], 0) + 1
        return {"total_extractions": len(self.extractions), "by_type": by_type}


# Test it:
ext = DocumentExtractor("Qwen/Qwen3-VL-2B-Instruct")
r1 = ext.extract("receipt.jpg", "receipt")
print(r1["merchant"], r1["total"])

r2 = ext.extract("bill.pdf", "invoice")
print(r2["vendor"], r2["amount_due"])

ext.add_schema("form", "Extract all field-value pairs")
r3 = ext.extract("form.png", "form")
print(r3["app_name"])

s = ext.summary()
print(s["total_extractions"])
print(sorted(s["by_type"].items()))

try:
    ext.extract("x.jpg", "unknown")
except ValueError:
    print("Unknown type")
